func firewallListDataSource() framework.ListDataSourceSpec[firewallListModel] {
	return framework.ListDataSourceSpec[firewallListModel]{
		TypeName: "_firewalls_firewalls",
		Schema:   firewallListSchema(),
		List: func(ctx context.Context, client *core.Client, m *firewallListModel) error {
			m.Firewalls = []firewallItemModel{}
			page, err := firewallsv1.NewFirewallClient(client).ListFirewalls(ctx, &firewallsv1.ListFirewallsRequest{Parent: "projects/" + m.Project.ValueString()})
			if err != nil {
				return err
			}
			for _, p := range page.GetFirewalls() {
				var item firewallItemModel
				if err := firewallItemFromProto(p, &item); err != nil {
					return err
				}
				m.Firewalls = append(m.Firewalls, item)
			}
			return nil
		},
	}
}
